# 20.11, партия 10, планы 1110–1215: технику под напряжением гоблин предлагал разбирать самому (микроволновку,
# телевизор, бойлер) — опасно; как с электрикой в партии 8: проверить простое, потом мастер или сервис
def _appl(t, x, home, gen=''):
    tail = ['Найти мастера по ремонту ' + gen + ' и договориться о визите', 'Показать мастеру, что не так, и узнать цену до ремонта'] if home else ['Найти сервисный центр и узнать цену и срок', 'Отнести ' + x + ' в сервис и взять квитанцию']
    e(t, steps=['Проверить, что вилка в розетке и сама розетка работает', 'Посмотреть в инструкции раздел про неисправности или код ошибки', 'Если техника на гарантии, найти чек и гарантийный талон'] + tail, why='гоблин предлагал разбирать технику под напряжением самому')
for _t, _x, _g in [('Починить бойлер', 'бойлер', 'бойлеров'), ('Починить кондиционер', 'кондиционер', 'кондиционеров'), ('Починить стиральную машину', 'машинка', 'стиральных машин'), ('Починить холодильник', 'холодильник', 'холодильников')]:
    _appl(_t, _x, True, _g)
for _t, _x in [('Починить микроволновку', 'микроволновку'), ('Починить телевизор', 'телевизор'), ('Починить утюг', 'утюг'), ('Починить фен', 'фен'), ('Починить чайник', 'чайник')]:
    _appl(_t, _x, False)
for _t, _w in [('Починить выключатель', 'выключатель'), ('Починить люстру', 'люстра'), ('Починить светильник', 'светильник')]:
    e(_t, steps=['Проверить, не перегорела ли лампочка', 'Посмотреть в щитке, не выбило ли автомат', 'Описать, что не так: ' + _w + ' искрит, не включается или мигает', 'Вызвать электрика через управляющую компанию или сервис', 'Проверить работу после ремонта'], why='гоблин предлагал лезть в проводку самому')
e('Поставить водонагреватель', steps=['Выбрать объём водонагревателя под семью', 'Измерить место, где он будет висеть', 'Купить водонагреватель с установкой или найти сантехника', 'Освободить место и доступ к трубам', 'После установки проверить, что вода нагревается и нигде не капает'], why='гоблин расписал монтаж своими руками')
